// Planner provenance gate (#1107). Scans the planner's AUTHORED artifacts (the section files it
// writes from reviewed repos/web) for injection markers, and turns the findings into a gate the
// user crosses before the plan seeds the fleet. Two modes:
//
//   - default (acknowledge-to-clear): findings are surfaced; the user reviews and acknowledges them
//     to proceed (a flag can be a false positive — kickoffs/sections legitimately contain
//     instructions — so the gate is on REVIEW, not on zero-flags).
//   - hard gate (Settings toggle `injectionHardGate`): any finding BLOCKS promotion until the
//     flagged content is removed — no acknowledge bypass.
//
// THE SCAN ITSELF NOW RUNS IN THE BACKEND (`the-planner-provenance-gate-scans-in-rust`, under
// `epic-frontend-logic-over-backend-resources-belongs-in-rust`). `planner::injection_scan` was ported
// and proved match-for-match against the TypeScript first, without flipping anything; this module is
// the flip. The artifacts are the backend's — the planner's section files and the kickoffs under
// `projects/<key>/prompts/` — so the thing that decides is now the thing that owns the resource.
//
// WHY BOTH SCANNERS STILL RUN, AND WHY THE RESULT IS A UNION. This is a security gate, and the only
// failure that matters here is LOSING a finding. So the two scans are reconciled by union, never by
// replacement: a marker EITHER side reports is reported. A union has that property structurally —
// it cannot be smaller than either input — which is why it is the reconciliation rule rather than
// "trust the backend" or "trust the renderer". When the two agree (which is what the parity fixture
// says they do) the union is exactly what the renderer produced before this flip, so landing it does
// not move what the user sees. When they disagree ONE OF THEM IS WRONG, and picking a winner in code
// would bury that; instead the disagreement is logged naming the artifact, line and match.
//
// THE TYPESCRIPT SCANNER IS DELIBERATELY NOT DELETED. Its removal is gated on that disagreement
// record being empty in the field, not on a fixture passing on one machine. Deleting it here would
// throw away the only evidence that the port is right in production.
//
// No React. The detection lives in the shared lib/security/injectionScan and in the Rust module it
// was ported to.

import { scanArtifacts, type InjectionFinding } from "@/shared/lib/security/injectionScan";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { log } from "@/shared/lib/core/log";

export type { InjectionFinding };

/** The log scope disagreements and backend outages are recorded under, so `bsc logs` can answer
 *  "has this ever disagreed in the field?" — the question that gates deleting the TypeScript. */
const SCOPE = "planner";

/** One artifact as the backend command takes it.
 *
 *  AN ORDERED LIST, NOT THE MAP. `scanArtifacts` walks `Object.entries`, so insertion order is
 *  visible in the output, and the Rust takes a slice of pairs for exactly that reason. Sending an
 *  object would let a `BTreeMap`-shaped deserialization sort the artifacts where nobody would see
 *  it — and since the two lists are compared element-wise, a sort on one side would report every
 *  finding as a disagreement. */
export interface ScanArtifact {
  file: string;
  text: string;
}

/** The `sections` map as the wire carries it — `Object.entries` order, preserved. */
export function toScanArtifacts(sections: Record<string, string>): ScanArtifact[] {
  return Object.entries(sections ?? {}).map(([file, text]) => ({ file, text: text ?? "" }));
}

/** A finding's identity for reconciliation: THE WHOLE RECORD, every field.
 *
 *  Not `file:line:category` (that is `injectionSignature`'s job, where collapsing is the point).
 *  Here a difference in the matched span or the context line is itself a disagreement worth seeing,
 *  so nothing is dropped from the key. Within one scanner duplicates cannot arise — each pattern
 *  matches at most once per line — so keying on the whole record can only collapse a finding
 *  against its identical twin FROM THE OTHER SIDE, which is agreement, not loss. */
function identity(f: InjectionFinding): string {
  return JSON.stringify([f.file, f.line, f.category, f.label, f.match, f.context]);
}

/** A finding exactly one of the two scanners reported. */
export interface InjectionDisagreement {
  /** Which scanner saw it — the other one did not. */
  side: "backend" | "renderer";
  finding: InjectionFinding;
}

export interface InjectionReconcile {
  /** The UNION of both scans, backend order first, then whatever only the renderer saw. */
  findings: InjectionFinding[];
  /** The symmetric difference — empty when the two scanners agree. */
  disagreements: InjectionDisagreement[];
}

/** Reconcile the backend scan and the renderer scan by UNION, never replacement.
 *
 *  The result contains every element of both inputs, so it cannot be smaller than either — that is
 *  the property the gate needs and the reason there is no "authoritative" side. Order is
 *  backend-first because the backend is the scanner this flip moved to; on agreement the two lists
 *  are identical and the union is that same list, unchanged, which is what makes the flip a no-op. */
export function reconcileInjections(
  backend: InjectionFinding[],
  renderer: InjectionFinding[],
): InjectionReconcile {
  const seen = new Set<string>();
  const findings: InjectionFinding[] = [];
  for (const f of [...backend, ...renderer]) {
    const k = identity(f);
    if (seen.has(k)) continue;
    seen.add(k);
    findings.push(f);
  }
  const backendKeys = new Set(backend.map(identity));
  const rendererKeys = new Set(renderer.map(identity));
  const disagreements: InjectionDisagreement[] = [
    ...backend.filter((f) => !rendererKeys.has(identity(f))).map((f) => ({ side: "backend" as const, finding: f })),
    ...renderer.filter((f) => !backendKeys.has(identity(f))).map((f) => ({ side: "renderer" as const, finding: f })),
  ];
  return { findings, disagreements };
}

/** The one-line record of a disagreement. NAMES THE ARTIFACT, THE LINE AND THE MATCH, because the
 *  reader of this line has to be able to reproduce it against both scanners without any other
 *  context — it is the evidence that decides whether the TypeScript copy can go. */
export function formatInjectionDisagreement(d: InjectionDisagreement): string {
  const f = d.finding;
  const other = d.side === "backend" ? "renderer" : "backend";
  return `injection scan disagreement: only the ${d.side} scanner flagged ${f.file}:${f.line} ${JSON.stringify(f.match)} (${f.category}/${f.label}); the ${other} scanner did not`;
}

/** Scan the planner-authored section files for injection markers.
 *
 *  Asks the backend (`planner_injection_scan`), which owns the artifacts, and reconciles its answer
 *  with the renderer's own scan by union. A backend that cannot answer is an OUTAGE, not a
 *  disagreement: it degrades to the renderer's findings alone — never fewer — and says so in the
 *  log, so an unreachable backend can never be mistaken for a clean scan. */
export async function findPlanInjections(sections: Record<string, string>): Promise<InjectionFinding[]> {
  const renderer = scanArtifacts(sections);
  const backend = await safeInvoke<InjectionFinding[] | null>(
    "planner_injection_scan",
    { artifacts: toScanArtifacts(sections) },
    null,
  );
  if (!Array.isArray(backend)) {
    log.warn("injection scan: the backend scanner did not answer; reporting the renderer's findings alone", SCOPE);
    return renderer;
  }
  const { findings, disagreements } = reconcileInjections(backend, renderer);
  for (const d of disagreements) log.warn(formatInjectionDisagreement(d), SCOPE);
  return findings;
}

/** A stable, order-independent signature of a finding set. A user's "reviewed" acknowledgement is
 *  keyed by this, so adding new injected content (a new finding) invalidates the ack and re-gates. */
export function injectionSignature(findings: InjectionFinding[]): string {
  return findings.map((f) => `${f.file}:${f.line}:${f.category}`).sort().join("|");
}

export type InjectionGateMode = "clear" | "review" | "blocked";

export interface InjectionGate {
  findings: InjectionFinding[];
  /** `clear` = nothing flagged; `review` = flagged, acknowledge-to-clear available; `blocked` = the
   *  hard gate is on, so the flagged content must be removed (no acknowledgement bypass). */
  mode: InjectionGateMode;
  /** Whether plan → fleet promotion may proceed. */
  cleared: boolean;
}

/** Resolve the gate from findings + the hard-gate setting + the user's acknowledged signature. */
export function injectionGate(
  findings: InjectionFinding[],
  opts: { hardGate: boolean; ackSig?: string },
): InjectionGate {
  if (findings.length === 0) return { findings, mode: "clear", cleared: true };
  if (opts.hardGate) return { findings, mode: "blocked", cleared: false };
  return { findings, mode: "review", cleared: opts.ackSig === injectionSignature(findings) };
}
